// Middleware: enforce audience and binding
function cbjwtGuard(req, res, next){
  const token = req.headers.authorization?.split(' ')[1]
  const payload = verifyCBJWT(token)
  if (!payload.aud.includes(expectedTenant)) return res.status(403).send('invalid audience')
  if (!payload.certificate_fingerprint) return res.status(403).send('missing binding')
  next()
